BEGIN;
PRAGMA writable_schema = on;
PRAGMA encoding = 'UTF-8';
PRAGMA page_size = '4096';
PRAGMA auto_vacuum = '0';
PRAGMA user_version = '0';
PRAGMA application_id = '0';
CREATE TABLE "label_template_versions" (
    "id" TEXT NOT NULL CONSTRAINT "PK_label_template_versions" PRIMARY KEY,
    "template_id" TEXT NOT NULL,
    "version" INTEGER NOT NULL,
    "template_json" TEXT NOT NULL,
    "created_by" TEXT NULL,
    "created_at" TEXT NOT NULL
);
CREATE TABLE "label_templates" (
    "id" TEXT NOT NULL CONSTRAINT "PK_label_templates" PRIMARY KEY,
    "name" TEXT NOT NULL,
    "description" TEXT NULL,
    "dpi" INTEGER NOT NULL,
    "label_width" REAL NOT NULL,
    "label_height" REAL NOT NULL,
    "template_json" TEXT NOT NULL,
    "version" INTEGER NOT NULL,
    "is_active" INTEGER NOT NULL,
    "updated_at" TEXT NOT NULL,
    "created_at" TEXT NOT NULL
, status TEXT NOT NULL DEFAULT 'published', is_default INTEGER NOT NULL DEFAULT 0, created_by TEXT, updated_by TEXT, note TEXT, layout_type TEXT NOT NULL DEFAULT '1UP', sheet_columns INTEGER NOT NULL DEFAULT 1, sheet_rows INTEGER NOT NULL DEFAULT 1, gap_mm REAL NOT NULL DEFAULT 0, SubmittedBy TEXT, ApprovedAt TEXT, ApprovedBy TEXT, template_code TEXT, category TEXT, orientation TEXT NOT NULL DEFAULT 'PORTRAIT', revision TEXT NOT NULL DEFAULT 'A', supported_barcode_types TEXT, supported_printer_models TEXT, compatible_station_types TEXT);
CREATE TABLE "print_history" (
    "id" TEXT NOT NULL CONSTRAINT "PK_print_history" PRIMARY KEY,
    "template_id" TEXT NOT NULL,
    "template_name" TEXT NOT NULL,
    "template_version" INTEGER NOT NULL,
    "printer_code" TEXT NOT NULL,
    "runtime_data_json" TEXT NOT NULL,
    "rendered_zpl" TEXT NOT NULL,
    "tcp_request_hex" TEXT NULL,
    "tcp_response_hex" TEXT NULL,
    "printer_result" TEXT NULL,
    "status" TEXT NOT NULL,
    "duration_ms" INTEGER NOT NULL,
    "retry_count" INTEGER NOT NULL,
    "trace_id" TEXT NOT NULL,
    "correlation_id" TEXT NOT NULL,
    "exception_message" TEXT NULL,
    "timeline_json" TEXT NULL,
    "created_at" TEXT NOT NULL
);
CREATE TABLE "printer_events" (
    "id" TEXT NOT NULL CONSTRAINT "PK_printer_events" PRIMARY KEY,
    "printer_id" TEXT NOT NULL,
    "event_type" TEXT NOT NULL,
    "event_data" TEXT NULL,
    "occurred_at" TEXT NOT NULL,
    "created_at" TEXT NOT NULL
);
CREATE TABLE "printer_jobs" (
    "id" TEXT NOT NULL CONSTRAINT "PK_printer_jobs" PRIMARY KEY,
    "job_id" TEXT NOT NULL,
    "attempt_id" TEXT NOT NULL,
    "printer_id" TEXT NOT NULL,
    "label_template" TEXT NOT NULL,
    "rendered_content" TEXT NOT NULL,
    "print_status" TEXT NOT NULL,
    "copies" INTEGER NOT NULL,
    "sent_at" TEXT NULL,
    "finished_at" TEXT NULL,
    "error_message" TEXT NULL,
    "created_at" TEXT NOT NULL
);
CREATE TABLE "printer_printers" (
    "id" TEXT NOT NULL CONSTRAINT "PK_printer_printers" PRIMARY KEY,
    "printer_code" TEXT NOT NULL,
    "display_name" TEXT NOT NULL,
    "ip_address" TEXT NOT NULL,
    "port" INTEGER NOT NULL,
    "protocol" TEXT NOT NULL,
    "vendor" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "group_id" TEXT NULL,
    "last_heartbeat_at" TEXT NULL,
    "created_at" TEXT NOT NULL
, driver_type TEXT NOT NULL DEFAULT 'simulation', cups_queue_name TEXT, is_active_for_work INTEGER NOT NULL DEFAULT 0, active_template_id TEXT, active_template_name TEXT, activated_at TEXT, activated_by TEXT);
CREATE TABLE printer_template_assignments (
            id TEXT PRIMARY KEY,
            printer_code TEXT NOT NULL UNIQUE,
            template_id TEXT NOT NULL,
            template_name TEXT,
            assigned_by TEXT,
            assigned_at TEXT NOT NULL,
            created_at TEXT NOT NULL
        );
CREATE TABLE template_audit_events (
            id TEXT PRIMARY KEY, template_id TEXT NOT NULL, template_version INTEGER NOT NULL,
            action TEXT NOT NULL, actor TEXT, detail_json TEXT, created_at TEXT NOT NULL
        );
CREATE TABLE printer_outbox_messages (
            id TEXT PRIMARY KEY, event_type TEXT NOT NULL, aggregate_id TEXT NOT NULL,
            payload TEXT NOT NULL, status TEXT NOT NULL, published_at TEXT, created_at TEXT NOT NULL
        );
CREATE TABLE label_assets (
            id TEXT PRIMARY KEY, name TEXT NOT NULL, content_type TEXT NOT NULL,
            sha256 TEXT NOT NULL UNIQUE, content BLOB NOT NULL, is_active INTEGER NOT NULL,
            created_at TEXT NOT NULL
        , storage_path TEXT, print_settings_json TEXT);
CREATE UNIQUE INDEX "IX_printer_printers_printer_code" on printer_printers(printer_code);
